namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nMozzarella cheese\nFresh basil\nSan Marzano tomatoes\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F\n2. Roll out dough on floured surface\n3. Spread crushed tomatoes evenly\n4. Add torn mozzarella pieces\n5. Drizzle with olive oil\n6. Bake 10-12 minutes until crust is golden\n7. Top with fresh basil leaves", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook pasta in salted water until al dente\n2. Crisp guanciale in a pan\n3. Whisk eggs with grated pecorino and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture\n6. Serve immediately with extra pecorino", AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nCrushed tomatoes\nHeavy cream\nGarlic\nGinger\nOnion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or broil chicken until charred\n3. Sauté onion, garlic, and ginger\n4. Add spices and cook until fragrant\n5. Add crushed tomatoes, simmer 15 minutes\n6. Stir in cream and cooked chicken\n7. Simmer 10 minutes, serve with rice", AverageRating = 4.7, RatingCount = 15 },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs", Steps = "1. Soak rice noodles in warm water 30 minutes\n2. Make sauce: mix tamarind, fish sauce, sugar\n3. Press and cube tofu, pan-fry until golden\n4. Scramble eggs in wok\n5. Add drained noodles and sauce\n6. Toss with bean sprouts and green onions\n7. Serve with crushed peanuts and lime wedge", AverageRating = 4.3, RatingCount = 8 },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet\n2. Add taco seasoning and water, simmer 5 minutes\n3. Warm tortillas in a dry pan\n4. Assemble tacos with beef and toppings\n5. Serve with salsa and sour cream", AverageRating = 4.1, RatingCount = 10 },
            new() { Id = 6, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste\nCoconut milk\nChicken breast\nBamboo shoots\nThai basil\nFish sauce\nPalm sugar\nBell peppers\nThai eggplant", Steps = "1. Heat coconut cream in a wok until oil separates\n2. Fry curry paste until fragrant\n3. Add sliced chicken, cook through\n4. Pour in remaining coconut milk\n5. Add vegetables and bamboo shoots\n6. Season with fish sauce and sugar\n7. Garnish with Thai basil", AverageRating = 4.6, RatingCount = 11 },
            new() { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Stir in diced onion, jalapeño, and tomato\n4. Add lime juice, cilantro, and garlic\n5. Season with salt\n6. Serve immediately with chips", AverageRating = 4.4, RatingCount = 18 },
            new() { Id = 8, Title = "Butter Chicken", Category = "Indian", Ingredients = "Chicken thighs\nButter\nTomato puree\nHeavy cream\nGaram masala\nKashmiri chili\nFenugreek leaves\nGarlic\nGinger\nYogurt", Steps = "1. Marinate chicken in yogurt and spices overnight\n2. Grill or pan-fry chicken pieces\n3. Melt butter, sauté garlic and ginger\n4. Add tomato puree, simmer 20 minutes\n5. Stir in cream and spices\n6. Add chicken, simmer 10 minutes\n7. Finish with fenugreek leaves and butter", AverageRating = 4.9, RatingCount = 25 },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}
"}

